package android.content;import android.net.Uri;import android.database.Cursor;import java.io.*;public final class ContentResolver {final Context c;ContentResolver(Context c){this.c=c;}File file(Uri u){java.util.List<String> p=u.getPathSegments();return new File(new Context(c.root,Integer.parseInt(p.get(0))).getFilesDir(),"saved-downloads/"+p.get(1)+"/"+p.get(2));}public OutputStream openOutputStream(Uri u,String mode)throws IOException{return new FileOutputStream(file(u));}public Uri insert(Uri uri,ContentValues values){throw new UnsupportedOperationException("Host does not emulate MediaStore");}public int update(Uri uri,ContentValues values,String where,String[] args){throw new UnsupportedOperationException("Host does not emulate MediaStore");}public int delete(Uri u,String where,String[] args){return file(u).delete()?1:0;}public Cursor query(Uri u,String[] columns,String where,String[] args,String order){File f=file(u);return new Cursor(){public boolean moveToFirst(){return f.isFile();}public String getString(int i){throw new UnsupportedOperationException();}public int getInt(int i){throw new UnsupportedOperationException();}public long getLong(int i){return f.length();}public boolean isNull(int i){return false;}public void close(){}};}}
